#include <iostream>
using namespace std;

int main() {
    int mas[9][9];

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            cin >> mas[i][j];
        }
    }

    int iz, jz;
    cin >> iz >> jz;
    --iz;
    --jz;

    if (iz >= 0 && iz < 9 && jz >= 0 && jz < 9 &&
        mas[iz][jz] != 33 && mas[iz][jz] != 46) {
        int row = (iz / 3) * 3;
        int col = (jz / 3) * 3;

        for (int i = row; i < row + 3; ++i) {
            for (int j = col; j < col + 3; ++j) {
                if (mas[i][j] != 120 && mas[i][j] != 111) {
                    mas[i][j] = 33;
                }
            }
        }
    }

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            cout << static_cast<char>(mas[i][j]) << ' ';
        }
        cout << '\n';
    }

    return 0;
}

